import assert from 'node:assert/strict';import{mkdir,writeFile,readFile}from'node:fs/promises';import{resolve}from'node:path';import{build,preview}from'vite';import react from'@vitejs/plugin-react';import tailwindcss from'@tailwindcss/vite';import{chromium}from'playwright';import{especialidades}from'../src/lib/especialidades.ts';
const fase=process.env.QA_FASE||'depois',root=resolve('output/cadastros-compras-velocidade-20261118'),out=resolve(process.env.QA_OUTPUT||resolve(root,process.env.QA_ADVERSOS_OUT||'adversos-'+fase)),src=resolve(fase==='antes'?root+'/antes/src':'src');await mkdir(out,{recursive:true});
await build({configFile:false,envDir:false,logLevel:'error',plugins:[{name:'rpc-qa',enforce:'pre',resolveId(s){if(s==='@audit/Fornecedores')return resolve(src,fase==='antes'?'pages/Compras.tsx':'pages/Fornecedores.tsx');if(/^(\.\.\/)+lib\/rpc$/.test(s)||s==='./rpc')return resolve('scripts/fixtures/cadastros-agilidade-rpc.js')}},react(),tailwindcss()],resolve:{alias:{'@audit/Fornecedores':resolve(src,fase==='antes'?'pages/Compras.tsx':'pages/Fornecedores.tsx'),'@audit':src}},define:{'import.meta.env.VITE_SUPABASE_URL':'""','import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY':'""'},build:{outDir:resolve(out,'build'),rollupOptions:{input:'scripts/fixtures/cadastros-agilidade.html'}}});
const server=await preview({configFile:false,build:{outDir:resolve(out,'build')},preview:{host:'127.0.0.1',port:0}}),base=`http://127.0.0.1:${server.httpServer.address().port}/scripts/fixtures/cadastros-agilidade.html`;
const browser=await chromium.launch({headless:true,executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe'}),ctx=await browser.newContext({viewport:{width:390,height:844},locale:'pt-BR'}),p=await ctx.newPage();p.setDefaultTimeout(6000);const resultados=[],falhas=[],erros=[];p.on('pageerror',e=>erros.push(e.message));
const guardar=()=>writeFile(resolve(out,'resultados.json'),JSON.stringify({fase,resultados,falhas,erros},null,2));
const teste=async(perfil,nome,fn)=>{try{const dados=await fn();resultados.push({perfil,nome,...dados,ok:true})}catch(e){falhas.push({perfil,nome,erro:e.message});await p.screenshot({path:resolve(out,perfil+'-'+falhas.length+'.png')}).catch(()=>{})}await guardar()};
const ir=async(perfil,tela,extras='')=>p.goto(base+`?perfil=${perfil}&tela=${tela}${extras}`),d=()=>p.locator('dialog[open]').last();
const cases=[['funcionarios','Novo funcionário','nome','Salvar funcionário','salvar_funcionario'],['fornecedores','Novo fornecedor','nome','Salvar fornecedor','salvar_fornecedor'],['catalogo','Novo serviço','descricao','Salvar cadastro','salvar_servico_detalhado']];
try{
 for(const perfil of(process.env.QA_PERFIS?.split(',')||Object.keys(especialidades))){
  if(!process.env.QA_EXTRAS){
  for(const[tela,novo,campo,salvar,rpc]of cases){
   await teste(perfil,tela+' · salvar durante carga inicial',async()=>{await ir(perfil,tela,'&corrida');await p.getByRole('button',{name:novo,exact:true}).click();await d().locator(`[name=${campo}]`).fill('Cadastro QA');if(tela==='catalogo')await d().locator('[name=preco]').fill('100');await d().getByRole('button',{name:salvar,exact:true}).click();await p.locator('dialog[open]').waitFor({state:'hidden'});if(tela==='fornecedores')await p.getByRole('heading',{name:'Cadastro QA',exact:true}).waitFor();else await p.getByRole('button',{name:tela==='funcionarios'?'Abrir ficha de Cadastro QA':/Cadastro QA/}).first().waitFor();return{}});
   if(fase==='depois')await teste(perfil,tela+' · confirmar sem prender o próximo cadastro',async()=>{await ir(perfil,tela,'&lista-lenta');await p.getByRole('button',{name:novo,exact:true}).click();await d().locator('[name='+campo+']').fill('Cadastro QA');if(tela==='catalogo')await d().locator('[name=preco]').fill('100');const t=performance.now();await d().getByRole('button',{name:salvar,exact:true}).click();await p.locator('dialog[open]').waitFor({state:'hidden'});const segundos=(performance.now()-t)/1000;assert(segundos<1.5);await p.getByRole('button',{name:novo,exact:true}).click();await d().locator('[name='+campo+']').fill('Próximo cadastro');await p.waitForFunction(()=>window.qaCache.isFetching()===0);assert.equal(await d().locator('[name='+campo+']').inputValue(),'Próximo cadastro');return{segundos}});
   await teste(perfil,tela+' · duplo envio e erro recuperável',async()=>{await ir(perfil,tela,'&falhar');await p.getByRole('button',{name:novo,exact:true}).click();await d().locator(`[name=${campo}]`).fill('Cadastro QA');if(tela==='catalogo')await d().locator('[name=preco]').fill('100');const f=tela==='funcionarios'?d().locator('#cadastro-funcionario'):d().locator('form').first();await f.evaluate(f=>{f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}))});await d().getByRole('alert').waitFor();assert.equal(await d().locator(`[name=${campo}]`).inputValue(),'Cadastro QA');assert.equal(await p.evaluate(n=>window.qaChamadas.filter(c=>c.nome===n).length,rpc),1);await d().getByRole('button',{name:salvar,exact:true}).click();await p.locator('dialog[open]').waitFor({state:'hidden'});assert.equal(await p.evaluate(n=>window.qaChamadas.filter(c=>c.nome===n).length,rpc),2);return{}});
  }
  await teste(perfil,'Localização · busca sem consulta a cada tecla',async()=>{await ir(perfil,'local');await p.locator('summary').click();await p.getByPlaceholder('Nome da bancada, armário ou prateleira').pressSequentially('Bancada',{delay:35});await p.getByRole('option',{name:'Bancada QA',exact:true}).waitFor({state:'attached'});await p.waitForFunction(()=>window.qaChamadas.some(c=>c.args.p_busca==='Bancada'));const consultas=await p.evaluate(()=>window.qaChamadas.filter(c=>c.nome==='listar_locais_fisicos').length);if(fase==='depois')assert(consultas<=2);return{consultas}});
  await teste(perfil,'Localização · duplo movimento',async()=>{await ir(perfil,'movimento');await p.getByRole('combobox',{name:'Onde vai ficar?',exact:true}).selectOption('local');await d().locator('form').evaluate(f=>{f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}))});await p.waitForFunction(()=>window.qaSalvo);const consultas=await p.evaluate(()=>window.qaChamadas.filter(c=>c.nome==='movimentar_itens_fisicos').length);assert.equal(consultas,1);return{consultas}});
  await teste(perfil,'Compras · tecla Enter só seleciona resultado seguro',async()=>{await ir(perfil,'busca');const input=p.getByRole('combobox');await input.fill('vários');await input.press('Enter');assert.equal(await p.locator('output').innerText(),'');await input.fill('carregando');await input.press('Enter');assert.equal(await p.locator('output').innerText(),'');await input.fill('único');await input.press('Enter');assert.equal(await p.locator('output').innerText(),'a');return{}});
  await teste(perfil,'Compras · painel secundário lento',async()=>{await ir(perfil,'integracoes');await p.waitForFunction(()=>window.qaFinanceiro===1);const t=performance.now();await p.getByRole('button',{name:'Salvar pedido',exact:true}).click();await p.getByText('Salvo',{exact:true}).waitFor();const segundos=(performance.now()-t)/1000;if(fase==='depois')assert(segundos<1.5);await p.waitForFunction(()=>window.qaFinanceiro===2);return{segundos,financeiroAtualizado:true}});
  }
  if(process.env.QA_EXTRAS){const{extras}=await import('./cadastros-extras-20261118.mjs');await extras({p,d,ir,teste,perfil,fase,out})}
  console.log('ADVERSOS',fase,perfil,resultados.length,falhas.length);
 }
 if(fase==='depois')assert.equal(falhas.length,0);assert.deepEqual(erros,[]);
}finally{await guardar();await browser.close();await new Promise(r=>server.httpServer.close(r))}
